const items = $input.all();
const emails = items.map(item => {
  const d = item.json;
  return {
    id: d.id || '',
    subject: d.subject || '(no subject)',
    from: d.from?.name || d.from?.address || d.from || 'unknown',
    fromEmail: d.from?.address || d.from || '',
    snippet: d.snippet || '',
    text: d.textPlain || d.text || d.snippet || '',
    date: d.date || new Date().toISOString(),
    hasAttachments: (d.attachments || []).length > 0
  };
});

return [{ json: { emails, count: emails.length } }];

const email = $input.first().json;
const results = [];

for (const e of email.emails) {
  const text = (e.subject + ' ' + e.snippet).toLowerCase();

  // Classification rules
  let category = 'other';
  let priority = 'low';

  // Promotions / Marketing
  if (text.match(/unsubscribe|promo|sale|discount|offer|% off|deal|black friday|cyber|marketing|newsletter|weekly digest|monthly update/)) {
    category = 'promotion';
    priority = 'low';
  }
  // Social / Notifications
  else if (text.match(/notification|alert|reminder|verify|confirm|reset password|security|login|sign.?in|account|subscription|joined|followed|commented|replied|liked/)) {
    category = 'notification';
    priority = 'low';
  }
  // Spam / Automated
  else if (text.match(/noreply|no-reply|donotreply|automated|auto-generated|receipt|invoice|order #|tracking|shipment|delivery/)) {
    category = 'automated';
    priority = 'low';
  }
  // Important - direct human communication
  else if (text.match(/urgent|important|action.?required|deadline|meeting|interview|offer|contract|proposal|asap|priority|decision|review|feedback|question|discuss|call|sync/)) {
    category = 'important';
    priority = 'high';
  }
  // Job / Career
  else if (text.match(/job|position|hiring|recruit|interview|resume|candidate|career|opportunity|apply/)) {
    category = 'career';
    priority = 'high';
  }
  // Financial
  else if (text.match(/bank|payment|transfer|balance|statement|tax|salary|invest|crypto|stock|dividend/)) {
    category = 'financial';
    priority = 'medium';
  }
  // Personal / Direct
  else if (e.fromEmail && !e.fromEmail.match(/@gmail|@yahoo|@hotmail|@outlook|@google|@github|@linkedin|@medium|@substack/)) {
    category = 'personal';
    priority = 'medium';
  }
  else {
    category = 'other';
    priority = 'medium';
  }

  results.push({
    ...e,
    category,
    priority
  });
}

return [{ json: { emails: results, total: results.length } }];

const data = $input.first().json;
const important = data.emails.filter(e => 
  e.priority === 'high' || 
  e.priority === 'medium' ||
  e.category === 'important' ||
  e.category === 'career' ||
  e.category === 'financial' ||
  e.category === 'personal'
);

const summary = {
  high: important.filter(e => e.priority === 'high').length,
  medium: important.filter(e => e.priority === 'medium').length,
  low: data.emails.filter(e => e.priority === 'low').length,
  total: data.total
};

return [{ json: { important, summary, allEmails: data.emails } }];

const data = $input.first().json;

const emailList = data.important.map((e, i) => {
  return `Email ${i + 1}:
From: ${e.from} <${e.fromEmail}>
Subject: ${e.subject}
Snippet: ${e.snippet}
Category: ${e.category} | Priority: ${e.priority}`;
}).join('\n\n---\n\n');

const systemPrompt = `You are an email summarizer AI. Analyze the emails and create a clean daily digest.

Rules:
1. Group emails by importance (high priority first)
2. For each email provide: sender, subject, one-line summary, and action needed (if any)
3. At the end, give an overall priority score (1-10) for how urgent the inbox is
4. Use clean formatting with emojis for categories
5. Be concise - this is a mobile-friendly digest
6. Total emails received today: ${data.summary.total}
7. Important: ${data.summary.high} high, ${data.summary.medium} medium, ${data.summary.low} low priority`;

const userPrompt = `Summarize these emails into a clean digest:\n\n${emailList}`;

return [{ json: { systemPrompt, userPrompt, emailCount: data.important.length } }];

const response = $input.first().json;
const summaryData = $('Build AI Prompt').first().json;
const filterData = $('Filter Important Emails').first().json;

const aiSummary = response.message?.content || response.response || 'Could not generate summary.';

const header = `📬 **Email Digest** — ${new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n` +
  `📊 ${filterData.summary.total} emails today | ${filterData.summary.high} urgent | ${filterData.summary.medium} important | ${filterData.summary.low} low priority\n` +
  `━━━━━━━━━━━━━━━━━━━━━━\n\n`;

const fullDigest = header + aiSummary;

return [{ json: { digest: fullDigest, emailCount: summaryData.emailCount } }];
